Table users {
  id uuid [pk]
  full_name varchar(200)
  email varchar(320) [unique]
}

Table items {
  id uuid [pk]
  reporter_id uuid [ref: > users.id]
  title varchar(120)
  status varchar(20)
}

Table claims {
  id uuid [pk]
  item_id uuid [ref: > items.id]
  claimant_id uuid [ref: > users.id]
  status varchar(20)
}
